from flask import Flask, request, redirect

app = Flask(__name__)

@app.route('/')
def redirect():
    '''
    Redirect the user to the next_url specified on the GET request. If the next_url is not provided or does not start with a trusted base URL, it will be redirected to a default safe page.
    '''
    next_url = request.args.get('next_url')

    # Define a list of trusted base URLs
    trusted_base_urls = ['https://example.com', 'http://trustedsite.com']

    if next_url and any(next_url.startswith(base) for base in trusted_base_urls):
        return redirect(next_url)
    else:
        # Default safe page URL
        default_safe_page = "https://example.com/default"
        return redirect(default_safe_page)
